111	fn main() {
112	    tracing_subscriber::fmt()
113	        .with_env_filter(EnvFilter::from_default_env())
114	        .with_writer(std::io::stderr)
115	        .init();
116	
117	    let cli = Cli::parse();
118	
119	    let result = match cli.command {
120	        Commands::Init { global } => hooks::install(global),
121	        Commands::Uninit { global } => hooks::uninstall(global),
122	        Commands::Wrap { command } => wrap::execute(&command),
123	        Commands::Stats { json, days, waste } => stats::show(json, days, waste),
124	        Commands::Sync { once, api_url } => {
125	            let mut config = sync::SyncConfig { one_shot: once, ..Default::default() };
126	            if let Some(url) = api_url {
127	                config.api_url = url;
128	            }
129	            sync::run(config)
130	        }
131	        Commands::Login { auth_url } => auth::login(auth_url.as_deref()),
132	        Commands::Status => auth::status(),
133	        Commands::Logout => auth::logout(),
134	        Commands::Route { command, tokens, files } => handle_route(&command, tokens, &files),
135	
136	        Commands::Cache { action } => handle_cache(action),
137	        Commands::Hook { action } => handle_hook(action),
138	        Commands::Update => {
139	            println!("codeflow {}", env!("CARGO_PKG_VERSION"));
140	            println!("commit:  {}", option_env!("CODEFLOW_GIT_SHA").unwrap_or("dev"));
141	            println!("target:  {}", env!("TARGET"));
142	            println!();
143	            println!("Update: download latest from https://github.com/codeflow-dev/codeflow/releases");
144	            Ok(())
145	        }
146	    };
147	
148	    if let Err(e) = result {
149	        tracing::error!("{:#}", e);
150	        std::process::exit(1);
151	    }
152	}
