154	fn handle_route(command: &str, tokens: u64, files: &[String]) -> anyhow::Result<()> {
155	    let cmd = command.to_string();
156	    if cmd.is_empty() {
157	        anyhow::bail!("no command provided");
158	    }
159	
160	    let file_refs: Vec<&str> = files.iter().map(|f| f.as_str()).collect();
161	    let extensions = codeflow_core::router::extensions_from_paths(&file_refs);
162	
163	    let input = codeflow_core::router::RoutingInput {
164	        command: cmd.clone(),
165	        context_tokens: tokens,
166	        file_extensions: extensions,
167	        session_event_count: 0,
168	    };
169	
170	    let decision = codeflow_core::router::classify(&input);
171	
172	    println!("Command:    {}", cmd);
173	    println!("Tokens:     {}", tokens);
174	    println!("Score:      {:.2}", decision.score);
175	    println!("Complexity: {:?}", decision.complexity);
176	    println!("Route to:   {} (${}/1M tokens)", decision.tier.name(), decision.tier.cost_per_million_tokens());
177	    println!("Savings:    {:.0}% vs Opus", decision.estimated_savings_pct);
178	    if !decision.reason.is_empty() {
179	        println!("Reason:     {}", decision.reason);
180	    }
181	
182	    Ok(())
183	}
