185	fn handle_cache(action: CacheAction) -> anyhow::Result<()> {
186	    let db_path = paths::db_path();
187	    match action {
188	        CacheAction::Clear => {
189	            if db_path.exists() {
190	                let cache = codeflow_core::dedup::DedupCache::open(&db_path, "")?;
191	                let removed = cache.clear()?;
192	                println!("Cleared {} cache entries.", removed);
193	            } else {
194	                println!("Cache is empty.");
195	            }
196	            Ok(())
197	        }
198	        CacheAction::Info => {
199	            if db_path.exists() {
200	                let cache = codeflow_core::dedup::DedupCache::open(&db_path, "")?;
201	                let count = cache.entry_count()?;
202	                println!("Cache entries: {}", count);
203	                println!("Database: {}", db_path.display());
204	            } else {
205	                println!("No cache database found.");
206	            }
207	            Ok(())
208	        }
209	    }
210	}
