219	fn handle_pre_tool_use() -> anyhow::Result<()> {
220	    let input = match read_stdin() {
221	        Ok(s) => s,
222	        Err(e) => {
223	            eprintln!("[codeflow] hook health-check: stdin read failed: {}", e);
224	            println!("{{}}");
225	            return Ok(());
226	        }
227	    };
228	
229	    let parsed: serde_json::Value = match serde_json::from_str(&input) {
230	        Ok(v) => v,
231	        Err(e) => {
232	            eprintln!(
233	                "[codeflow] hook health-check: invalid JSON from Claude Code: {}",
234	                e
235	            );
236	            println!("{{}}");
237	            return Ok(());
238	        }
239	    };
240	
241	    if !parsed.is_object() {
242	        eprintln!(
243	            "[codeflow] hook health-check: expected JSON object, got {}",
244	            parsed
245	        );
246	        println!("{{}}");
247	        return Ok(());
248	    }
249	
250	    let tool_name = match parsed.get("tool_name").and_then(|v| v.as_str()) {
251	        Some(name) => name,
252	        None => {
253	            println!("{{}}");
254	            return Ok(());
255	        }
256	    };
257	
258	    let tool_input = match parsed.get("tool_input") {
259	        Some(v) if v.is_object() => v,
260	        _ => {
261	            println!("{{}}");
262	            return Ok(());
263	        }
264	    };
265	
266	    // Log to session + dedup check (single connection, best-effort)
267	    let session_id = codeflow_core::util::session_id();
268	    let file_path = codeflow_core::session::extract_file_path(tool_name, tool_input);
269	    let session_log = open_session_log(&session_id).ok();
270	
271	    if let Some(ref sl) = session_log {
272	        let tool_input_str = serde_json::to_string(tool_input).unwrap_or_default();
273	        if let Ok(row_id) =
274	            sl.record_pre(tool_name, &tool_input_str, file_path.as_deref())
275	        {
276	            sl.write_pre_id(tool_name, file_path.as_deref(), row_id);
277	        }
278	    }
279	
280	    match tool_name {
281	        "Bash" => {
282	            if let Some(command) = tool_input.get("command").and_then(|c| c.as_str()) {
283	                if should_wrap(command) {
284	                    let codeflow_bin = std::env::current_exe()
285	                        .map(|p| p.to_string_lossy().to_string())
286	                        .unwrap_or_else(|_| "codeflow".to_string());
287	                    let quoted_bin = shell_quote(&codeflow_bin);
288	                    let rewritten = format!("{} wrap {}", quoted_bin, command);
289	                    let response = serde_json::json!({
290	                        "tool_input": {
291	                            "command": rewritten
292	                        }
293	                    });
294	                    println!("{}", serde_json::to_string(&response)?);
295	                    return Ok(());
296	                }
297	            }
298	            println!("{{}}");
299	        }
300	        "Read" | "Grep" | "Glob" => {
301	            if let Some(ref session_log) = session_log {
302	                let window_secs = std::env::var("CODEFLOW_DEDUP_WINDOW_SECS")
303	                    .ok()
304	                    .and_then(|v| v.parse().ok());
305	                let dedup =
306	                    codeflow_core::read_dedup::ReadDedup::new(session_log, window_secs);
307	                let tool_input_str = serde_json::to_string(tool_input).unwrap_or_default();
308	
309	                let result = match tool_name {
310	                    "Read" => {
311	                        if let Some(fp) = file_path.as_deref() {
312	                            dedup.check_read(fp)
313	                        } else {
314	                            codeflow_core::read_dedup::ReadDedupResult::Miss
315	                        }
316	                    }
317	                    "Grep" => dedup.check_grep(&tool_input_str),
318	                    "Glob" => dedup.check_glob(&tool_input_str),
319	                    _ => codeflow_core::read_dedup::ReadDedupResult::Miss,
320	                };
321	
322	                match result {
323	                    codeflow_core::read_dedup::ReadDedupResult::Hit {
324	                        context_message,
325	                        tokens_saved,
326	                    } => {
327	                        let response = serde_json::json!({
328	                            "additionalContext": context_message
329	                        });
330	                        println!("{}", serde_json::to_string(&response).unwrap_or_default());
331	
332	                        // Track savings
333	                        if tokens_saved > 0 {
334	                            if let Ok(tracking) =
335	                                codeflow_core::tracking::TrackingDb::open(&paths::db_path())
336	                            {
337	                                let _ = tracking.record(
338	                                    &codeflow_core::tracking::TrackingEvent {
339	                                        command: tool_name.to_string(),
340	                                        input_tokens: tokens_saved,
341	                                        output_tokens: 0,
342	                                        tokens_saved,
343	                                        layer:
344	                                            codeflow_core::tracking::SavingsLayer::ReadDedup,
345	                                        project: std::env::current_dir()
346	                                            .unwrap_or_default()
347	                                            .to_string_lossy()
348	                                            .to_string(),
349	                                        session_id: session_id.clone(),
350	                                    },
351	                                );
352	                            }
353	                        }
354	                        return Ok(());
355	                    }
356	                    codeflow_core::read_dedup::ReadDedupResult::Miss => {
357	                        println!("{{}}");
358	                    }
359	                }
360	            } else {
361	                println!("{{}}");
362	            }
363	        }
364	        _ => {
365	            println!("{{}}");
366	        }
367	    }
368	
369	    Ok(())
370	}
