372	fn handle_post_tool_use() -> anyhow::Result<()> {
373	    let input = match read_stdin() {
374	        Ok(s) => s,
375	        Err(_) => {
376	            println!("{{}}");
377	            return Ok(());
378	        }
379	    };
380	
381	    let parsed: serde_json::Value = serde_json::from_str(&input).unwrap_or_default();
382	    let tool_name = parsed.get("tool_name").and_then(|v| v.as_str());
383	    let tool_result = parsed
384	        .get("tool_result")
385	        .and_then(|v| v.as_str())
386	        .unwrap_or("");
387	
388	    if let Some(tn) = tool_name {
389	        if matches!(tn, "Read" | "Grep" | "Glob" | "Bash") {
390	            let file_path = parsed
391	                .get("tool_input")
392	                .and_then(|ti| codeflow_core::session::extract_file_path(tn, ti));
393	
394	            let session_id = codeflow_core::util::session_id();
395	            if let Ok(session_log) = open_session_log(&session_id) {
396	                if let Some(row_id) = session_log.take_pre_id(tn, file_path.as_deref()) {
397	                    let capped = if tool_result.len() > 1_048_576 {
398	                        &tool_result[..1_048_576]
399	                    } else {
400	                        tool_result
401	                    };
402	                    let content_hash =
403	                        blake3::hash(capped.as_bytes()).to_hex().to_string();
404	                    let token_count = codeflow_core::util::estimate_tokens(tool_result.len()) as i64;
405	
406	                    let mtime_ns =
407	                        file_path.as_deref().and_then(codeflow_core::util::get_file_mtime_ns);
408	
409	                    let _ = session_log.record_post(
410	                        row_id,
411	                        &content_hash,
412	                        token_count,
413	                        mtime_ns,
414	                    );
415	                }
416	            }
417	        }
418	    }
419	
420	    println!("{{}}");
421	    Ok(())
422	}
