424	fn open_session_log(
425	    session_id: &str,
426	) -> anyhow::Result<codeflow_core::session::SessionLog> {
427	    let db_path = paths::db_path();
428	    let data_dir = paths::data_dir();
429	    std::fs::create_dir_all(&data_dir)?;
430	    codeflow_core::session::SessionLog::open(&db_path, session_id)
431	}
