449	fn shell_quote(s: &str) -> String {
450	    if s.contains(' ') || s.contains('\\') || s.contains('\'') || s.contains('"') {
451	        format!("'{}'", s.replace('\'', "'\\''"))
452	    } else {
453	        s.to_string()
454	    }
455	}
456	
457	fn read_stdin() -> anyhow::Result<String> {
458	    use std::io::Read;
459	    let mut buf = String::new();
460	    std::io::stdin().read_to_string(&mut buf)?;
461	    Ok(buf)
462	}
