31	func (f *fakeStorage) GetOverview(_ context.Context, tenantID string) (*clickhouse.OverviewStats, error) {
32		f.mu.Lock()
33		defer f.mu.Unlock()
34	
35		stats := &clickhouse.OverviewStats{}
36		cmdMap := make(map[string]*clickhouse.CommandStat)
37	
38		for _, e := range f.events {
39			if e.TenantID != tenantID {
40				continue
41			}
42			stats.TotalInputTokens += e.InputTokens
43			stats.TotalOutputTokens += e.OutputTokens
44			stats.TotalSaved += e.TokensSaved
45			stats.EventCount++
46	
47			if cs, ok := cmdMap[e.Command]; ok {
48				cs.Saved += e.TokensSaved
49				cs.Count++
50			} else {
51				cmdMap[e.Command] = &clickhouse.CommandStat{
52					Command: e.Command,
53					Saved:   e.TokensSaved,
54					Count:   1,
55				}
56			}
57		}
58	
59		if stats.TotalInputTokens > 0 {
60			stats.SavingsPct = float64(stats.TotalSaved) / float64(stats.TotalInputTokens) * 100
61		}
62	
63		for _, cs := range cmdMap {
64			stats.TopCommands = append(stats.TopCommands, *cs)
65		}
66	
67		return stats, nil
68	}
