70	func (f *fakeStorage) GetProjects(_ context.Context, tenantID string) ([]clickhouse.ProjectSummary, error) {
71		f.mu.Lock()
72		defer f.mu.Unlock()
73	
74		projMap := make(map[string]*clickhouse.ProjectSummary)
75		for _, e := range f.events {
76			if e.TenantID != tenantID {
77				continue
78			}
79			p, ok := projMap[e.ProjectDir]
80			if !ok {
81				p = &clickhouse.ProjectSummary{ProjectDir: e.ProjectDir}
82				projMap[e.ProjectDir] = p
83			}
84			p.TotalSaved += e.TokensSaved
85			p.TotalInput += e.InputTokens
86			p.EventCount++
87			p.LastEventAt = e.Timestamp.Format(time.RFC3339)
88		}
89	
90		for _, p := range projMap {
91			if p.TotalInput > 0 {
92				p.SavingsPct = float64(p.TotalSaved) / float64(p.TotalInput) * 100
93			}
94		}
95	
96		var result []clickhouse.ProjectSummary
97		for _, p := range projMap {
98			result = append(result, *p)
99		}
100		return result, nil
101	}
