103	func (f *fakeStorage) GetProjectStats(_ context.Context, tenantID, projectDir string) (*clickhouse.ProjectStats, error) {
104		f.mu.Lock()
105		defer f.mu.Unlock()
106	
107		ps := &clickhouse.ProjectStats{ProjectDir: projectDir}
108		for _, e := range f.events {
109			if e.TenantID != tenantID || e.ProjectDir != projectDir {
110				continue
111			}
112			ps.Summary.TotalSaved += e.TokensSaved
113			ps.Summary.TotalInput += e.InputTokens
114			ps.Summary.EventCount++
115			ps.Summary.LastEventAt = e.Timestamp.Format(time.RFC3339)
116		}
117		ps.Summary.ProjectDir = projectDir
118		if ps.Summary.TotalInput > 0 {
119			ps.Summary.SavingsPct = float64(ps.Summary.TotalSaved) / float64(ps.Summary.TotalInput) * 100
120		}
121		return ps, nil
122	}
