124	func (f *fakeStorage) GetSavingsTrend(_ context.Context, tenantID string, days int) ([]clickhouse.DailySavings, error) {
125		f.mu.Lock()
126		defer f.mu.Unlock()
127	
128		dayMap := make(map[string]*clickhouse.DailySavings)
129		cutoff := time.Now().AddDate(0, 0, -days)
130	
131		for _, e := range f.events {
132			if e.TenantID != tenantID || e.Timestamp.Before(cutoff) {
133				continue
134			}
135			day := e.Timestamp.Format("2006-01-02")
136			d, ok := dayMap[day]
137			if !ok {
138				d = &clickhouse.DailySavings{Day: day}
139				dayMap[day] = d
140			}
141			d.TotalSaved += e.TokensSaved
142			d.TotalInput += e.InputTokens
143			d.EventCount++
144			if e.EventType == "compression" {
145				d.Compression += e.TokensSaved
146			}
147			if e.EventType == "dedup" {
148				d.Dedup += e.TokensSaved
149			}
150		}
151	
152		var result []clickhouse.DailySavings
153		for _, d := range dayMap {
154			result = append(result, *d)
155		}
156		return result, nil
157	}
